-- KeyGo initial schema. Requires MySQL 8.0+, InnoDB and utf8mb4.
CREATE DATABASE IF NOT EXISTS keygo CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE keygo;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, email_normalized VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', email_verified_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL UNIQUE, phone VARCHAR(40), billing_name VARCHAR(160), identity_document VARCHAR(80), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE customer_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, label VARCHAR(80), address_line1 VARCHAR(255) NOT NULL, address_line2 VARCHAR(255), city VARCHAR(100) NOT NULL, country_code CHAR(2) NOT NULL, reference_note VARCHAR(255), contact_name VARCHAR(160), contact_phone VARCHAR(40), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, country_code CHAR(2) NOT NULL, timezone VARCHAR(64) NOT NULL, address_line1 VARCHAR(255) NOT NULL, address_line2 VARCHAR(255), city VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE lockers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id, role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE user_warehouse_access (user_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id, warehouse_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL, revoked_at DATETIME(3), last_used_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE account_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(40) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL, consumed_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE policy_acceptances (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, policy_version VARCHAR(40) NOT NULL, accepted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(user_id, policy_version), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE warehouse_locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED, code VARCHAR(64) NOT NULL, type VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(warehouse_id, code), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(parent_id) REFERENCES warehouse_locations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE carriers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, normalization_rules JSON, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE prealerts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, carrier_id BIGINT UNSIGNED, tracking_raw VARCHAR(160) NOT NULL, tracking_normalized VARCHAR(160) NOT NULL, store VARCHAR(120), description VARCHAR(255), declared_value DECIMAL(14,2), currency CHAR(3), status VARCHAR(40) NOT NULL DEFAULT 'SUBMITTED', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX(carrier_id, tracking_normalized), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(carrier_id) REFERENCES carriers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE packages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED, prealert_id BIGINT UNSIGNED, carrier_id BIGINT UNSIGNED, tracking_raw VARCHAR(160), tracking_normalized VARCHAR(160), warehouse_id BIGINT UNSIGNED, location_id BIGINT UNSIGNED, logistic_status VARCHAR(40) NOT NULL DEFAULT 'RECEIVED_USA', received_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX(customer_id, logistic_status, received_at, id), INDEX(warehouse_id, logistic_status, received_at, id), INDEX(carrier_id, tracking_normalized), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(prealert_id) REFERENCES prealerts(id) ON DELETE RESTRICT, FOREIGN KEY(carrier_id) REFERENCES carriers(id) ON DELETE RESTRICT, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(location_id) REFERENCES warehouse_locations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE package_measurements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, weight_kg DECIMAL(12,3) NOT NULL, length_cm DECIMAL(12,2) NOT NULL, width_cm DECIMAL(12,2) NOT NULL, height_cm DECIMAL(12,2) NOT NULL, input_unit VARCHAR(10), actor_id BIGINT UNSIGNED NOT NULL, measured_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE package_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, from_location_id BIGINT UNSIGNED, to_location_id BIGINT UNSIGNED, actor_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(from_location_id) REFERENCES warehouse_locations(id) ON DELETE RESTRICT, FOREIGN KEY(to_location_id) REFERENCES warehouse_locations(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE package_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, event_code VARCHAR(50) NOT NULL, from_status VARCHAR(40), to_status VARCHAR(40), actor_id BIGINT UNSIGNED, occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), customer_visible BOOLEAN NOT NULL DEFAULT FALSE, observation TEXT, INDEX(package_id, occurred_at, id), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE consolidations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, origin_warehouse_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'REQUESTED', requested_by BIGINT UNSIGNED NOT NULL, prepared_by BIGINT UNSIGNED, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(origin_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(prepared_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE consolidation_items (consolidation_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, added_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), removed_at DATETIME(3), actor_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(consolidation_id, package_id), FOREIGN KEY(consolidation_id) REFERENCES consolidations(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE cargo_reservations (package_id BIGINT UNSIGNED PRIMARY KEY, consolidation_id BIGINT UNSIGNED, shipment_id BIGINT UNSIGNED, reserved_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(consolidation_id) REFERENCES consolidations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE shipments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, consolidation_id BIGINT UNSIGNED, method ENUM('AIR','SEA') NOT NULL, origin_warehouse_id BIGINT UNSIGNED NOT NULL, destination_warehouse_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'REQUESTED', destination_snapshot JSON NOT NULL, requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version INT UNSIGNED NOT NULL DEFAULT 1, INDEX(customer_id,status,requested_at,id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(consolidation_id) REFERENCES consolidations(id) ON DELETE RESTRICT, FOREIGN KEY(origin_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(destination_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT) ENGINE=InnoDB;
ALTER TABLE cargo_reservations ADD CONSTRAINT fk_cargo_reservation_shipment FOREIGN KEY (shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT;
CREATE TABLE shipment_packages (shipment_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, confirmed_measurement_id BIGINT UNSIGNED, added_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(shipment_id,package_id), FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(confirmed_measurement_id) REFERENCES package_measurements(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE shipment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, shipment_id BIGINT UNSIGNED NOT NULL, from_status VARCHAR(40), to_status VARCHAR(40), actor_id BIGINT UNSIGNED, occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), observation TEXT, INDEX(shipment_id,occurred_at,id), FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE dispatch_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, code VARCHAR(32) NOT NULL UNIQUE, method ENUM('AIR','SEA') NOT NULL, origin_warehouse_id BIGINT UNSIGNED NOT NULL, destination_warehouse_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', dispatched_at DATETIME(3), received_at DATETIME(3), FOREIGN KEY(origin_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(destination_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE batch_shipments (shipment_id BIGINT UNSIGNED PRIMARY KEY, batch_id BIGINT UNSIGNED NOT NULL, assigned_by BIGINT UNSIGNED NOT NULL, assigned_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT, FOREIGN KEY(batch_id) REFERENCES dispatch_batches(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE batch_receipt_items (batch_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, result VARCHAR(30) NOT NULL, received_by BIGINT UNSIGNED NOT NULL, received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), incident_id BIGINT UNSIGNED, PRIMARY KEY(batch_id,package_id), FOREIGN KEY(batch_id) REFERENCES dispatch_batches(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(received_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE rate_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, version INT UNSIGNED NOT NULL, method ENUM('AIR','SEA') NOT NULL, origin_warehouse_id BIGINT UNSIGNED, destination_warehouse_id BIGINT UNSIGNED, currency CHAR(3) NOT NULL, effective_from DATETIME(3) NOT NULL, effective_to DATETIME(3), active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(code,version), FOREIGN KEY(origin_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(destination_warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE rate_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rate_plan_id BIGINT UNSIGNED NOT NULL, concept VARCHAR(120) NOT NULL, basis VARCHAR(40) NOT NULL, divisor DECIMAL(12,3), minimum_amount DECIMAL(14,2), rounding_rule VARCHAR(40), amount DECIMAL(14,2) NOT NULL, FOREIGN KEY(rate_plan_id) REFERENCES rate_plans(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED, input_snapshot JSON NOT NULL, rule_version VARCHAR(80) NOT NULL, breakdown JSON NOT NULL, currency CHAR(3) NOT NULL, total DECIMAL(14,2) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, shipment_id BIGINT UNSIGNED NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, code VARCHAR(32) NOT NULL UNIQUE, status ENUM('DRAFT','ISSUED','VOID') NOT NULL DEFAULT 'DRAFT', currency CHAR(3) NOT NULL, issued_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(customer_id,status,issued_at,id), FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoice_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, concept VARCHAR(160) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_amount DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, rule_snapshot JSON, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoice_packages (invoice_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, financial_version INT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY(invoice_id,package_id), INDEX(package_id), FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoice_line_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_line_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, allocated_amount DECIMAL(14,2) NOT NULL, allocation_rule_snapshot JSON, FOREIGN KEY(invoice_line_id) REFERENCES invoice_lines(id) ON DELETE RESTRICT, FOREIGN KEY(invoice_id,package_id) REFERENCES invoice_packages(invoice_id,package_id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoice_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, debit_or_credit ENUM('DEBIT','CREDIT') NOT NULL, amount DECIMAL(14,2) NOT NULL, reason TEXT NOT NULL, approved_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE invoice_adjustment_allocations (adjustment_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, allocated_amount DECIMAL(14,2) NOT NULL, PRIMARY KEY(adjustment_id,package_id), FOREIGN KEY(adjustment_id) REFERENCES invoice_adjustments(id) ON DELETE RESTRICT, FOREIGN KEY(invoice_id,package_id) REFERENCES invoice_packages(invoice_id,package_id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, account_reference VARCHAR(255), instructions TEXT, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE payment_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, code VARCHAR(32) NOT NULL UNIQUE, currency CHAR(3) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'DRAFT', total_snapshot DECIMAL(14,2) NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_order_items (order_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, amount_snapshot DECIMAL(14,2) NOT NULL, financial_version_snapshot INT UNSIGNED NOT NULL, PRIMARY KEY(order_id,invoice_id,package_id), FOREIGN KEY(order_id) REFERENCES payment_orders(id) ON DELETE RESTRICT, FOREIGN KEY(invoice_id,package_id) REFERENCES invoice_packages(invoice_id,package_id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, order_id BIGINT UNSIGNED NOT NULL, reported_by BIGINT UNSIGNED NOT NULL, method_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, reference VARCHAR(160) NOT NULL, paid_at_reported DATETIME(3) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'SUBMITTED', reviewed_by BIGINT UNSIGNED, review_reason TEXT, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(status,created_at,id), FOREIGN KEY(order_id) REFERENCES payment_orders(id) ON DELETE RESTRICT, FOREIGN KEY(reported_by) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(method_id) REFERENCES payment_methods(id) ON DELETE RESTRICT, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED, report_id BIGINT UNSIGNED UNIQUE, method_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, currency CHAR(3) NOT NULL, reference VARCHAR(160) NOT NULL, confirmed_by BIGINT UNSIGNED NOT NULL, confirmed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(order_id) REFERENCES payment_orders(id) ON DELETE RESTRICT, FOREIGN KEY(report_id) REFERENCES payment_reports(id) ON DELETE RESTRICT, FOREIGN KEY(method_id) REFERENCES payment_methods(id) ON DELETE RESTRICT, FOREIGN KEY(confirmed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, UNIQUE(invoice_id,package_id,payment_id), FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT, FOREIGN KEY(invoice_id,package_id) REFERENCES invoice_packages(invoice_id,package_id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_reversals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, reason TEXT NOT NULL, approved_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_reversal_allocations (reversal_id BIGINT UNSIGNED NOT NULL, payment_allocation_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, PRIMARY KEY(reversal_id,payment_allocation_id), FOREIGN KEY(reversal_id) REFERENCES payment_reversals(id) ON DELETE RESTRICT, FOREIGN KEY(payment_allocation_id) REFERENCES payment_allocations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE pickup_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL, code VARCHAR(32) NOT NULL UNIQUE, status VARCHAR(40) NOT NULL DEFAULT 'SUBMITTED', requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version INT UNSIGNED NOT NULL DEFAULT 1, INDEX(customer_id,warehouse_id,status), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE pickup_request_items (request_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), fulfilled_at DATETIME(3), PRIMARY KEY(request_id,package_id), FOREIGN KEY(request_id) REFERENCES pickup_requests(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE pickup_reservations (package_id BIGINT UNSIGNED PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL, reserved_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(request_id) REFERENCES pickup_requests(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, warehouse_id BIGINT UNSIGNED NOT NULL, pickup_request_id BIGINT UNSIGNED, recipient_snapshot JSON NOT NULL, delivered_by BIGINT UNSIGNED NOT NULL, delivered_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), method VARCHAR(40) NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE RESTRICT, FOREIGN KEY(pickup_request_id) REFERENCES pickup_requests(id) ON DELETE RESTRICT, FOREIGN KEY(delivered_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE delivery_items (delivery_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL UNIQUE, shipment_id BIGINT UNSIGNED NOT NULL, scanned_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(delivery_id,package_id), FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, object_key VARCHAR(512) NOT NULL UNIQUE, mime VARCHAR(120) NOT NULL, byte_size BIGINT UNSIGNED NOT NULL, checksum CHAR(64) NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE package_files (package_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(40) NOT NULL, customer_visible BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(package_id,file_id), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE payment_report_files (payment_report_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(payment_report_id,file_id), FOREIGN KEY(payment_report_id) REFERENCES payment_reports(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE prealert_files (prealert_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(40) NOT NULL, PRIMARY KEY(prealert_id,file_id), FOREIGN KEY(prealert_id) REFERENCES prealerts(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE delivery_files (delivery_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(delivery_id,file_id), FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE incidents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, package_id BIGINT UNSIGNED, shipment_id BIGINT UNSIGNED, category VARCHAR(50) NOT NULL, blocks_processing BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', assigned_to BIGINT UNSIGNED, resolution TEXT, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE package_claims (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', reviewed_by BIGINT UNSIGNED, resolution TEXT, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE claim_files (claim_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(claim_id,file_id), FOREIGN KEY(claim_id) REFERENCES package_claims(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE incident_files (incident_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(incident_id,file_id), FOREIGN KEY(incident_id) REFERENCES incidents(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(36) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED, invoice_id BIGINT UNSIGNED, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', assigned_to BIGINT UNSIGNED, subject VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX(assigned_to,status,updated_at,id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE ticket_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, internal_only BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE RESTRICT, FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE ticket_message_files (message_id BIGINT UNSIGNED NOT NULL, file_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(message_id,file_id), FOREIGN KEY(message_id) REFERENCES ticket_messages(id) ON DELETE RESTRICT, FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, type VARCHAR(80) NOT NULL, payload JSON NOT NULL, read_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(user_id,read_at,created_at,id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE notification_deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, notification_id BIGINT UNSIGNED NOT NULL, channel VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempts INT UNSIGNED NOT NULL DEFAULT 0, last_error TEXT, FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE push_subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, endpoint VARCHAR(512) NOT NULL UNIQUE, keys_json JSON NOT NULL, revoked_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE content_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(160) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, publication_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', seo JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE content_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, body LONGTEXT NOT NULL, approved_by BIGINT UNSIGNED, published_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(page_id) REFERENCES content_pages(id) ON DELETE RESTRICT, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED, action VARCHAR(100) NOT NULL, entity_reference VARCHAR(160) NOT NULL, safe_diff JSON, occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), request_id CHAR(36), FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE outbox_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(100) NOT NULL, aggregate_id BIGINT UNSIGNED NOT NULL, payload JSON NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempts INT UNSIGNED NOT NULL DEFAULT 0, available_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(status,available_at,id)) ENGINE=InnoDB;
CREATE TABLE idempotency_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, operation VARCHAR(100) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, request_hash CHAR(64) NOT NULL, result_reference VARCHAR(160), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(user_id,operation,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;